SELECT o.date_order_placed FROM Orders o JOIN Order_Items oi ON o.order_id = oi.order_id JOIN Products p ON oi.product_id = p.product_id WHERE o.date_order_placed IS NULL OR oi.quantity > 1;
SELECT order_date, order_item_status_code FROM Orders INNER JOIN Order_Items ON Orders.order_id = Order_Items.order_id WHERE Order_Items.order_item_status_code = 'P' AND (SELECT product_price FROM Products WHERE product_id = Order_Items.product_id) > 1;
SELECT customer_first_name, customer_middle_initial, customer_last_name FROM Customers WHERE customer_id NOT IN (SELECT customer_id FROM Orders WHERE order_id NOT IN (SELECT order_id FROM Order_Items WHERE order_item_status_code = 'Completed' OR order_item_status_code = 'Cancelled'))
SELECT customer_first_name, customer_middle_initial, customer_last_name, customer_middle_initial FROM Customers WHERE customer_last_name NOT IN (SELECT customer_last_name FROM Orders) AND customer_middle_initial IS NOT NULL;
SELECT p.id, p.name, p.price, p.color FROM Products p JOIN Order_Items oi ON p.product_id = oi.product_id JOIN Orders o ON oi.order_id = o.order_id JOIN Customers c ON o.customer_id = c.customer_id WHERE p.status = 'Not Ordered' AND p.status = 'Not Ordered' AND p.status = 'Not Ordered'
SELECT product_id, product_name, product_price, product_color FROM Products INNER JOIN Order_Items ON Products.product_id = Order_Items.product_id INNER JOIN Orders ON Order_Items.order_id = Orders.order_id INNER JOIN Customers ON Orders.customer_id = Customers.customer_id INNER JOIN Customer_Payment_Methods ON Orders.customer_id = Customer_Payment_Methods.customer_id WHERE Orders.order_status_code = '2' AND Orders.date_order_placed < '2023-01-01';
SELECT o.order_id, o.date_order_placed FROM Orders o JOIN Order_Items oi ON o.order_id = oi.order_id JOIN Products p ON oi.product_id = p.product_id WHERE p.product_price >= 2;
SELECT order_id, date_order_placed FROM Orders JOIN Order_Items ON Orders.order_id = Order_Items.order_id JOIN Products ON Order_Items.product_id = Products.product_id WHERE Order_Items.order_item_status_code = '2' GROUP BY order_id, date_order_placed
SELECT id, product_name, product_price FROM Products INNER JOIN Order_Items ON Products.product_id = Order_Items.product_id INNER JOIN Orders ON Order_Items.order_id = Orders.order_id INNER JOIN Customers ON Orders.customer_id = Customers.customer_id ORDER BY product_price DESC LIMIT 1;
SELECT p.product_id, c.customer_id, p.product_name, p.product_price, p.product_color, p.product_size, p.product_description FROM Products p JOIN Customers c ON p.parent_product_id = c.customer_id JOIN Order_Items oi ON p.product_id = oi.product_id JOIN Orders o ON oi.order_id = o.order_id JOIN Customer_Payment_Methods cp ON o.customer_id = cp.customer_id JOIN Invoices i ON o.invoice_number = i.invoice_number JOIN Shipments s ON o.order_id = s.order_id JOIN Shipment_Items si ON s.shipment_id = si.shipment_id WHERE oi.order_item_status_code = 'Active' AND p.product_price > (SELECT MAX(product_price) FROM Products) ORDER BY p.product_price DESC;
SELECT o.order_id, SUM(pi.product_price) AS sum_product_price FROM Orders o JOIN Order_Items pi ON o.order_id = pi.order_id GROUP BY o.order_id ORDER BY sum_product_price DESC LIMIT 1
SELECT MIN(product_price) AS total_cost, (SELECT SUM(product_price) FROM Order_Items) AS total_cost
SELECT DISTINCT payment_method_code FROM Customer_Payment_Methods;
SELECT DISTINCT payment_method_code FROM Customer_Payment_Methods ORDER BY payment_method_code ASC;
SELECT gender_code, COUNT(product_id) AS total_products_bought FROM Customers JOIN Order_Items ON Customers.customer_id = Order_Items.customer_id JOIN Products ON Order_Items.product_id = Products.product_id GROUP BY gender_code
