SELECT DISTINCT customer_id, gender_code, customer_first_name, customer_last_name, order_status_code, date_order_placed FROM Customers INNER JOIN Order_Items ON Customers.customer_id = Order_Items.customer_id INNER JOIN Orders ON Order_Items.order_id = Orders.order_id INNER JOIN Invoices ON Invoices.invoice_number = Shipments.invoice_number INNER JOIN Shipments ON Shipments.order_id = Orders.order_id;
SELECT customer_id, gender_code, COUNT(*) AS order_count FROM Customers INNER JOIN Order_Items ON Customers.customer_id = Order_Items.customer_id GROUP BY customer_id, gender_code
SELECT Customers.customer_first_name, Customers.customer_middle_initial, Customers.customer_last_name, Customer_Payment_Methods.payment_method_code AS payment_method FROM Customers LEFT JOIN Customer_Payment_Methods ON Customers.customer_id = Customer_Payment_Methods.customer_id;
SELECT customer_first_name, customer_middle_initial, customer_last_name, payment_method_code FROM Customers JOIN Customer_Payment_Methods ON Customers.customer_id = Customer_Payment_Methods.customer_id;
SELECT Invoices.invoice_status_code AS invoice_status, Invoices.invoice_date AS invoice_date, Shipments.shipment_date AS shipment_date FROM Invoices INNER JOIN Shipments ON Invoices.invoice_number = Shipments.invoice_number;
SELECT invoice_status_code, invoice_date, shipment_date FROM Invoices INNER JOIN Shipments ON Invoices.invoice_number = Shipments.invoice_number;
SELECT p.product_name, s.shipment_date FROM Products p JOIN Shipments s ON p.product_id = s.order_id JOIN Order_Items oi ON s.order_id = oi.order_id JOIN Orders o ON oi.order_id = o.order_id JOIN Customers c ON o.customer_id = c.customer_id JOIN Customer_Payment_Methods cp ON o.customer_id = cp.customer_id JOIN Invoices i ON s.invoice_number = i.invoice_number;
SELECT p.product_name, s.shipment_date FROM Products p JOIN Shipments s ON p.product_id = s.shipment_id;
SELECT order_item_status_code, shipment_tracking_number FROM Order_Items JOIN Shipments ON Order_Items.order_id = Shipments.order_id JOIN Invoices ON Shipments.invoice_number = Invoices.invoice_number;
SELECT order_item_status_code, shipment_tracking_number FROM Order_Items JOIN Shipments ON Order_Items.order_id = Shipments.order_id;
SELECT product_name, product_color FROM Products JOIN Order_Items ON Order_Items.product_id = Products.product_id JOIN Orders ON Orders.order_id = Order_Items.order_id JOIN Shipments ON Shipments.order_id = Orders.order_id JOIN Invoices ON Invoices.invoice_number = Shipments.invoice_number;
SELECT product_name, product_color FROM Products INNER JOIN Order_Items ON Products.product_id = Order_Items.product_id INNER JOIN Orders ON Order_Items.order_id = Orders.order_id INNER JOIN Shipments ON Orders.order_id = Shipments.order_id INNER JOIN Invoices ON Shipments.invoice_number = Invoices.invoice_number;
SELECT DISTINCT product_name, product_price, product_description FROM Products INNER JOIN Customers ON Products.product_id = Customers.customer_id WHERE Customers.gender_code = 'F' AND Customers.email_address IS NOT NULL;
SELECT product_name, product_price, product_description FROM Products JOIN Customer_Payment_Methods ON Customers.customer_id = Customer_Payment_Methods.customer_id JOIN Customers ON Customers.customer_id = Customers.customer_id WHERE Customers.gender_code = 'F' AND Customers.email_address IS NOT NULL;
SELECT Invoices.invoice_status_code FROM Invoices INNER JOIN Orders ON Invoices.invoice_number = Orders.order_id INNER JOIN Order_Items ON Orders.order_id = Order_Items.order_id INNER JOIN Products ON Order_Items.product_id = Products.product_id WHERE Order_Items.order_item_status_code = 'Not Shipped'
SELECT Invoices.invoice_status_code FROM Invoices INNER JOIN Orders ON Invoices.invoice_number = Orders.order_status_code WHERE Invoices.invoice_status_code != 'Shipped'
SELECT Order_Items.order_id, Orders.date_order_placed, Order_Items.total_cost FROM Orders JOIN Order_Items ON Orders.order_id = Order_Items.order_id;
SELECT Orders.order_id, Orders.date_order_placed, Orders.total_amount_paid FROM Orders JOIN Order_Items ON Orders.order_id = Order_Items.order_id JOIN Products ON Order_Items.product_id = Products.product_id;
