SELECT order_status_code, date_order_placed FROM Orders INNER JOIN Order_Items ON Orders.order_id = Order_Items.order_id INNER JOIN Products ON Order_Items.product_id = Products.product_id INNER JOIN Invoices ON Invoices.invoice_number = Shipments.invoice_number INNER JOIN Shipments ON Shipments.order_id = Orders.order_id;
SELECT order_status_code, date_order_placed FROM Orders JOIN Order_Items ON Orders.order_id = Order_Items.order_id JOIN Products ON Order_Items.product_id = Products.product_id JOIN Invoices ON Invoices.invoice_number = Shipments.invoice_number JOIN Shipments ON Shipments.order_id = Orders.order_id;
