SELECT Customers.town_city, Customers.county, Customers.country, Products.product_name, Orders.order_id FROM Customers INNER JOIN Orders ON Customers.customer_id = Orders.customer_id INNER JOIN Products ON Orders.order_item_id = Products.product_id;
SELECT C.customer_first_name, P.product_name FROM Customers C JOIN Products P ON C.customer_id = P.parent_product_id JOIN Order_Items O ON O.product_id = P.product_id JOIN Orders O2 ON O.order_id = O2.order_id JOIN Customer_Payment_Methods CPM ON O2.customer_id = CPM.customer_id;
SELECT c.customer_first_name, p.product_name, c.customer_last_name, p.product_price, p.product_color, p.product_size, p.product_description FROM Customers c JOIN Order_Items oi ON c.customer_id = oi.customer_id JOIN Products p ON oi.product_id = p.product_id JOIN Orders o ON oi.order_id = o.order_id JOIN Invoices i ON o.order_id = i.invoice_number JOIN Shipments s ON o.order_id = s.order_id JOIN Shipment_Items si ON s.shipment_id = si.shipment_id WHERE c.customer_first_name IS NOT NULL OR c.customer_last_name IS NOT NULL OR p.product_name IS NOT NULL OR p.product_price IS NOT NULL OR p.product_color IS NOT NULL OR p.product_size IS NOT NULL OR p.product_description IS NOT NULL;
