SELECT product_id, product_description FROM Products INNER JOIN Order_Items ON Products.product_id = Order_Items.product_id WHERE Order_Items.order_item_status_code = 'M' AND Order_Items.order_item_status_code = '3' GROUP BY product_id, product_description;
SELECT Invoices.invoice_date, Invoices.invoice_number FROM Invoices INNER JOIN Shipments ON Invoices.invoice_number = Shipments.invoice_number WHERE Invoices.invoice_status_code = 2 AND Shipments.order_id IN (SELECT order_id FROM Order_Items JOIN Orders ON Order_Items.order_id = Orders.order_id WHERE Orders.order_status_code = 2)
SELECT shipment_date, invoice_number FROM Shipments INNER JOIN Invoices ON Shipments.invoice_number = Invoices.invoice_number WHERE Invoices.invoice_status_code = 1 AND Invoices.invoice_date >= (SELECT invoice_date FROM Invoices WHERE invoice_status_code = 1 ORDER BY invoice_date LIMIT 1)
