SELECT director.Name FROM director WHERE Age > (SELECT AVG(Age) FROM director)
SELECT director.Name, director.Age FROM director JOIN program ON director.Director_ID = program.Director_ID JOIN channel ON program.Channel_ID = channel.Channel_ID WHERE director.Age = (SELECT MAX(Age) FROM director)
SELECT COUNT(*) FROM channel WHERE Internet LIKE '%bbc%'
SELECT COUNT(DISTINCT Digital_terrestrial_channel) FROM channel;
SELECT p.Title, p.Start_Year FROM program p JOIN channel c ON p.Channel_ID = c.Channel_ID ORDER BY p.Start_Year DESC;
SELECT director.Name, COUNT(program.Program_ID) AS total_programs FROM program JOIN director ON program.Director_ID = director.Director_ID GROUP BY director.Director_ID ORDER BY total_programs DESC;
SELECT d.Name, p.Age FROM director d JOIN program p ON d.Director_ID = p.Director_ID JOIN channel c ON p.Channel_ID = c.Channel_ID WHERE p.Start_Year IS NULL;
SELECT program.Title FROM program JOIN channel ON program.Channel_ID = channel.Channel_ID JOIN director ON program.Director_ID = director.Director_ID ORDER BY Start_Year DESC;
SELECT Name, Website_Link FROM channel JOIN program ON channel.Channel_ID = program.Channel_ID WHERE program.Director_ID IN (SELECT Director_ID FROM director_admin WHERE Is_first_director = TRUE)
SELECT channel.Name, COUNT(program.Program_ID) AS total_programs FROM program JOIN channel ON program.Channel_ID = channel.Channel_ID GROUP BY channel.Name
SELECT COUNT(DISTINCT channel.Channel_ID) FROM channel WHERE channel.Channel_ID NOT IN (SELECT Program_ID FROM program WHERE program.Channel_ID IS NULL OR program.Director_ID IS NULL)
