SELECT Name, Internet FROM channel JOIN program ON program.Channel_ID = channel.Channel_ID JOIN director ON program.Director_ID = director.Director_ID GROUP BY Name, Internet ORDER BY COUNT(Director_ID) DESC LIMIT 1
SELECT director.Name FROM director INNER JOIN program ON director.Director_ID = program.Director_ID WHERE program.Age >= 30 AND program.Age <= 60;
SELECT channel.Name FROM channel JOIN director ON channel.Channel_ID = director.Channel_ID WHERE director.Age < 40 AND director.Age > 60;
