SELECT radio.Radio_ID, radio.Transmitter, radio.Erp_kW FROM radio JOIN city_channel ON radio.Radio_ID = city_channel.Radio_ID ORDER BY radio.Erp_kW ASC
SELECT tv_show.tv_show_name, tv_show_original_airdate FROM tv_show INNER JOIN city_channel_tv_show ON tv_show.tv_show_ID = city_channel_tv_show.tv_show_ID;
