SELECT DISTINCT Affiliation, COUNT(*) AS Number_of_City_Channels_per_Affiliation FROM city_channel JOIN city_channel_radio ON city_channel.ID = city_channel_radio.City_channel_ID JOIN radio ON city_channel_radio.Radio_ID = radio.Radio_ID GROUP BY Affiliation
SELECT city_channel.Affiliation, city_channel.City, city_channel.Channel_ID FROM city_channel JOIN city_channel_radio ON city_channel.ID = city_channel_radio.City_channel_ID JOIN city_channel_tv_show ON city_channel.ID = city_channel_tv_show.City_channel_ID ORDER BY city_channel.Affiliation DESC LIMIT 1;
SELECT city_channel.Affiliation FROM city_channel JOIN city_channel_radio ON city_channel.ID = city_channel_radio.City_channel_ID WHERE city_channel.radio.Is_online = TRUE AND city_channel.radio.Radio_ID = radio.Radio_ID AND city_channel.radio.City_channel_ID = city_channel.ID AND city_channel.tv_show.Is_free = TRUE AND city_channel.tv_show.tv_show_ID = tv_show.tv_show_ID;
SELECT City, Station_name FROM city_channel ORDER BY Station_name ASC;
SELECT radio.Transmitter, city_channel.City AS City, city_channel_radio.Is_online AS Is_online FROM radio JOIN city_channel ON radio.Transmitter = city_channel.Transmitter JOIN city_channel_radio ON city_channel.City_channel_ID = city_channel_radio.City_channel_ID JOIN tv_show ON city_channel.tv_show_ID = tv_show.tv_show_ID JOIN city_channel_tv_show ON city_channel.tv_show_ID = city_channel_tv_show.tv_show_ID WHERE radio.Radio_MHz IS NOT NULL AND city_channel.Is_online = '1' AND radio.Radio_MHz IS NOT NULL;
SELECT radio.Radio_ID, radio.Transmitter, radio.Erp_kW, tv_show.tv_show_name FROM radio JOIN city_channel tv ON radio.Radio_ID = city_channel.Radio_ID JOIN tv_show tv_show ON tv.City_channel_ID = tv_show.tv_show_ID ORDER BY tv_show.tv_show_name DESC;
SELECT radio.Radio_ID, radio.Transmitter, radio.Radio_MHz, radio.2FM_MHz, radio.RnaG_MHz, radio.Lyric_FM_MHz, radio.EAR_Power_kW, city_channel.tv_show_ID, city_channel.tv_show_name, city_channel.Is_free, city_channel.Is_online FROM radio JOIN city_channel_radio ON radio.Radio_ID = city_channel_radio.Radio_ID JOIN city_channel ON city_channel.City_channel_ID = city_channel_radio.City_channel_ID JOIN tv_show ON city_channel.tv_show_ID = tv_show.tv_show_ID WHERE city_channel.Is_online = '1' AND city_channel.Is_free = '1';
