SELECT C.Customer_ID, C.Customer_Details, C.Service_Details FROM Customers C JOIN Customers_and_Services K ON C.Customer_ID = K.Customer_ID JOIN Services S ON K.Service_ID = S.Service_ID WHERE C.Customer_Details LIKE 'Hardy Kutch' AND K.Status_Code = 'bad' AND K.Customers_and_Services_Details IS NOT NULL;
SELECT Services.Service_Details FROM Services INNER JOIN Customers_and_Services ON Customers_and_Services.Customer_ID = Customers.Customer_ID INNER JOIN Customers ON Customers.Customer_ID = Customers_and_Services.Customer_ID INNER JOIN Services ON Customers_and_Services.Service_ID = Services.Service_ID WHERE Customers.Customer_Details = 'Hardy Kutch' AND Services.Service_Details = 'bad'
SELECT Service_Details FROM Services JOIN Customers_and_Services ON Customers_and_Services.Customer_ID = Customers.Customer_ID JOIN Customers ON Customers.Customer_ID = Customers_and_Services.Customer_ID JOIN Channels ON Customers_and_Services.Channel_ID = Channels.Channel_ID WHERE Service_Details LIKE '%15 ij%' AND Status_Code = 'X'
SELECT Service_Details FROM Services JOIN Customers_and_Services ON Customers_and_Services.Customer_ID = Customers.Customer_ID JOIN Customers ON Customers.Customer_ID = Customers_and_Services.Customer_ID WHERE Customer_Interactions.Channel_ID = 15 AND Customer_Interactions.Status_Code = 'ij'
SELECT Customer_Details, Customers_and_Services_Details FROM Customers_and_Services JOIN Customer_Interactions ON Customers_and_Services.Customer_ID = Customer_Interactions.Customer_ID JOIN Channels ON Customer_Interactions.Channel_ID = Channels.Channel_ID JOIN Integration_Platform ON Customer_Interactions.Customer_Interaction_ID = Integration_Platform.Customer_Interaction_ID WHERE Status_Code = 'Stuck' AND Services_and_Channels_Details = 'bad'
SELECT Customer_ID, Customer_Details FROM Customers WHERE Customer_Details LIKE '%Stuck%' AND Service_Details LIKE '%bad%' AND Status_Code = 'Stuck' AND Services_and_Channels_Details LIKE '%bad%'
SELECT COUNT(*) FROM Customers_and_Services INNER JOIN Customer_Interactions ON Customers_and_Services.Customer_ID = Customer_Interactions.Customer_ID;
SELECT COUNT(*) FROM Customers_and_Services WHERE Service_Details LIKE '%Success%';
SELECT Customers.Customer_ID, Customers_Customer_Services.Customers_and_Services_Details FROM Customers_and_Services INNER JOIN Customers_Customer_Services ON Customers_Customer_Services.Customers_and_Services_ID = Customers_and_Services.Customers_and_Services_ID WHERE Customers_Customer_Services.Status_Code = 'failed'
SELECT Customers.Customer_ID, Customers.Customer_Details FROM Customers INNER JOIN Customers_and_Services ON Customers.Customer_ID = Customers_and_Services.Customer_ID INNER JOIN Services ON Customers_and_Services.Service_ID = Services.Service_ID INNER JOIN Customer_Interactions ON Customers_Customer_ID = Customer_Interactions.Customer_ID INNER JOIN Channels ON Customer_Interactions.Channel_ID = Channels.Channel_ID INNER JOIN Integration_Platform ON Customer_Interactions.Customer_Interaction_ID = Integration_Platform.Customer_Interaction_ID WHERE Integration_Platform_Details = 'Fail';
SELECT s.Service_ID, s.Service_Details FROM Services s JOIN Customers_and_Services c ON c.Customer_ID = s.Service_ID WHERE c.Customers_and_Services_Details IS NULL;
SELECT Services.Service_Details FROM Services JOIN Customers_and_Services ON Customers_and_Services.Customer_ID = Customers.Customer_ID WHERE Customers_and_Services.Customers_and_Services_Details IS NULL
SELECT Customers_and_Services.Customers_and_Services_ID, Services.Service_Details, Customers_Customer_Interactions.Status_Code, Customers_Customer_Interactions.Service_ID, Customers_Customer_Interactions.Channel_ID, Customers_Customer_Interactions.Customer_ID, Customers_Customer_Interactions.Status_Code, Customers_and_Services.Customers_and_Services_Details FROM Customers_and_Services JOIN Customer_Interactions ON Customers_and_Services.Customer_ID = Customer_Interactions.Customer_ID JOIN Services ON Customer_Interactions.Service_ID = Services.Service_ID JOIN Channels ON Customer_Interactions.Channel_ID = Channels.Channel_ID JOIN Customers ON Customers_Customer_Interactions.Customer_ID = Customers.Customer_ID JOIN Analytical_Layer ON Customers_and_Services.Customers_and_Services_ID = Analytical_Layer.Customers_and_Services_ID;
SELECT Analytical_Layer.Analytical_Layer_Type_Code, COUNT(Customer_Interactions.Customer_ID) AS Usage_Count FROM Analytical_Layer INNER JOIN Customers_and_Services ON Analytical_Layer.Customers_and_Services_ID = Customers_and_Services.Customers_and_Services_ID GROUP BY Analytical_Layer.Analytical_Layer_Type_Code;
SELECT C.Customer_ID, C.Customer_Details, S.Service_Details, C.Customers_and_Services_Details FROM Customers C JOIN Customers_and_Services K ON C.Customer_ID = K.Customers_and_Services_ID JOIN Services S ON K.Service_ID = S.Service_ID WHERE K.Status_Code = 'unsatisfied'
SELECT Service_Details FROM Services INNER JOIN Customers_and_Services ON Customers_and_Services.Customer_ID = Customers.Customer_ID WHERE Status_Code = 'unsatisfied';
SELECT COUNT(*) FROM Customers;
SELECT COUNT(*) FROM Customers;
SELECT V.name, V.Model_year, V.Type_of_powertrain, V.Cost_per_25_miles, V.Annual_fuel_cost, V.Notes FROM Vehicles V ORDER BY V.Model_year DESC;
SELECT name, Model_year FROM Vehicles ORDER BY Model_year DESC;
SELECT DISTINCT Type_of_powertrain FROM Vehicles;
SELECT DISTINCT Type_of_powertrain FROM Vehicles;
SELECT Customers.name, Vehicles.Type_of_powertrain, Vehicles.Annual_fuel_cost FROM Customers INNER JOIN Vehicles ON Customers.id = Vehicles.customer_id WHERE Model_year IN ('2013', '2014')
SELECT Customers.name, Vehicles.Type_of_powertrain, Vehicles.Annual_fuel_cost FROM Customers INNER JOIN Vehicles ON Customers.id = Vehicles.customer_id WHERE Vehicles.Model_year IN (2013, 2014);
SELECT DISTINCT V.Type_of_powertrain FROM Vehicles V JOIN Renting_history R ON V.id = R.vehicles_id WHERE R.customer_id IN (SELECT id FROM Customers WHERE age < 2013 OR age > 2014) AND R.discount_id IN (SELECT id FROM Discount WHERE membership_credit IS NULL OR membership_credit IS NOT NULL AND membership_credit = 0)
SELECT DISTINCT V.Type_of_powertrain FROM Vehicles V JOIN Renting_history R ON V.id = R.vehicles_id JOIN Customers C ON R.customer_id = C.id WHERE R.Model_year IN (2013, 2014)
SELECT Type_of_powertrain, COUNT(Vehicles.id) AS Vehicle_Count FROM Vehicles JOIN Renting_history ON Vehicles.id = Renting_history.vehicles_id JOIN Customers ON Renting_history.customer_id = Customers.id GROUP BY Type_of_powertrain;
SELECT Type_of_powertrain, COUNT(*) AS count FROM Vehicles GROUP BY Type_of_powertrain
SELECT V.Type_of_powertrain, COUNT(V.id) AS vehicle_count FROM Vehicles V JOIN Renting_history R ON V.id = R.vehicles_id GROUP BY V.Type_of_powertrain ORDER BY COUNT(V.id) DESC;
SELECT Discount.name, COUNT(Vehicles.id) AS most_common_type_count FROM Discount JOIN Renting_history ON Discount.id = Renting_history.discount_id JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id GROUP BY Discount.id ORDER BY most_common_type_count DESC;
SELECT MIN(Annual_fuel_cost), MAX(Annual_fuel_cost), AVG(Annual_fuel_cost) FROM Vehicles;
SELECT AVG(Vehicles.Annual_fuel_cost), MAX(Vehicles.Annual_fuel_cost), MIN(Vehicles.Annual_fuel_cost) FROM Vehicles;
SELECT V.name, V.Model_year FROM Vehicles V JOIN Customers C ON V.customer_id = C.id WHERE V.City_fuel_economy_rate <= V.Highway_fuel_economy_rate;
SELECT name, Model_year FROM Vehicles WHERE City_fuel_economy_rate <= Highway_fuel_economy_rate;
SELECT V.Type_of_powertrain, AVG(V.Annual_fuel_cost) AS average_annual_fuel_cost FROM Vehicles V JOIN Renting_history R ON V.id = R.vehicles_id GROUP BY V.Type_of_powertrain HAVING COUNT(R.id) >= 2;
SELECT Discount.name, AVG(Vehicles.Annual_fuel_cost) AS average_annual_fuel_cost FROM Discount INNER JOIN Renting_history ON Discount.id = Renting_history.discount_id INNER JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id WHERE Vehicles.Type_of_powertrain = '2 or more vehicles' AND Discount.id = (SELECT Discount.id FROM Discount WHERE Discount.Type_of_powertrain = '2 or more vehicles')
SELECT Customers.name, Customers.age, Customers.membership_credit FROM Customers;
SELECT Customers.name, Customers.age, Customers.membership_credit FROM Customers;
SELECT Customers.name, Customers.age FROM Customers JOIN Discount ON Customers.id = Discount.discount_id JOIN Vehicles ON Customers.id = Vehicles.vehicles_id WHERE Customers.membership_credit = (SELECT MAX(membership_credit) FROM Customers)
SELECT name, age FROM Customers WHERE membership_credit = (SELECT MAX(membership_credit) FROM Customers)
SELECT AVG(age) FROM Customers WHERE membership_credit > (SELECT AVG(membership_credit) FROM Customers)
SELECT AVG(age) AS average_age FROM Customers WHERE membership_credit > (SELECT AVG(membership_credit) FROM Customers)
SELECT Customers.id, Customers.name, Customers.age, Customers.membership_credit, Discount.name, Discount.membership_credit, Vehicles.Model_year, Vehicles.Type_of_powertrain, Vehicles.Combined_fuel_economy_rate, Vehicles.City_fuel_economy_rate, Vehicles.Highway_fuel_economy_rate, Vehicles.Cost_per_25_miles, Vehicles.Annual_fuel_cost, Vehicles.Notes FROM Customers INNER JOIN Discount ON Customers.id = Discount.id INNER JOIN Vehicles ON Customers.id = Vehicles.id;
SELECT Customers.name, Discount.name, Vehicles.Model_year, Vehicles.Type_of_powertrain, Vehicles.Combined_fuel_economy_rate, Vehicles.City_fuel_economy_rate, Vehicles.Highway_fuel_economy_rate, Vehicles.Cost_per_25_miles, Vehicles.Annual_fuel_cost, Vehicles.Notes FROM Customers INNER JOIN Discount ON Customers.id = Discount.id JOIN Vehicles ON Vehicles.id = Renting_history.vehicles_id JOIN Customers ON Renting_history.customer_id = Customers.id;
SELECT Customers.name, SUM(Renting_history.total_hours) AS total_hours FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id GROUP BY Customers.id
SELECT Customers.name, SUM(Renting_history.total_hours) AS total_rental_hours FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id GROUP BY Customers.name
SELECT Customers.name FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id WHERE Renting_history.discount_id IS NULL;
SELECT DISTINCT Customers.name FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id WHERE Renting_history.discount_id IS NULL AND Vehicles.id IS NULL
SELECT Customers.name FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id WHERE Renting_history.discount_id = Discount.id AND Renting_history.vehicles_id = Vehicles.id AND COUNT(Renting_history.id) >= 2;
SELECT Customers.name FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id WHERE Renting_history.discount_id IS NOT NULL AND Renting_history.vehicles_id IS NOT NULL AND Renting_history.total_hours > 0;
SELECT Customers.name, Vehicles.Model_year FROM Customers INNER JOIN Vehicles ON Customers.id = Vehicles.id WHERE Customers.id = (SELECT Customers.id FROM Customers INNER JOIN Vehicles ON Customers.id = Vehicles.id GROUP BY Customers.id ORDER BY COUNT(Renting_history.id) DESC LIMIT 1)
SELECT Customers.name, Vehicles.Model_year FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id INNER JOIN Discount ON Renting_history.discount_id = Discount.id INNER JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id GROUP BY Customers.name, Vehicles.Model_year ORDER BY COUNT(Renting_history.id) DESC LIMIT 1;
SELECT Vehicles.name, Rentals.total_hours FROM Vehicles JOIN Rentals ON Vehicles.id = Rentals.vehicles_id ORDER BY Rentals.total_hours DESC;
SELECT name, total_hours FROM Renting_history INNER JOIN Customers ON Renting_history.customer_id = Customers.id INNER JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id ORDER BY total_hours DESC;
SELECT Discount.name, COUNT(Renting_history.id) AS total_renting_history FROM Customers INNER JOIN Discount ON Customers.id = Discount.id JOIN Renting_history ON Customers.id = Renting_history.customer_id JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id GROUP BY Discount.id ORDER BY total_renting_history DESC
SELECT Discount.name FROM Discount INNER JOIN Renting_history ON Discount.id = Renting_history.discount_id WHERE Renting_history.vehicles_id IS NULL OR Renting_history.customer_id IS NULL OR Discount.id = (SELECT Discount.id FROM Discount ORDER BY COUNT(Renting_history.discount_id) DESC LIMIT 1)
SELECT Customers.name, Vehicles.Type_of_powertrain FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id WHERE Vehicles.Combined_fuel_economy_rate > 30;
SELECT Customers.name, Vehicles.Type_of_powertrain FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id WHERE Vehicles.Combined_fuel_economy_rate > 30;
SELECT AVG(Vehicles.City_fuel_economy_rate) AS average_city_fuel_rate, AVG(Vehicles.Highway_fuel_economy_rate) AS average_highway_fuel_rate FROM Vehicles JOIN Customers ON Vehicles.customer_id = Customers.id JOIN Discount ON Vehicles.discount_id = Discount.id;
SELECT DISTINCT V.Type_of_powertrain, AVG(V.City_fuel_economy_rate) AS avg_city, AVG(V.Highway_fuel_economy_rate) AS avg_highway FROM Vehicles V JOIN Renting_history R ON V.id = R.vehicles_id GROUP BY V.Type_of_powertrain;
SELECT AVG(S.Student_Loans.amount_of_loan) AS average_loan_amount FROM Student_Loans;
SELECT AVG(loan_amount) FROM Student_Loans;
