nd, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary, D.datetime_detention_start, D.datetime_detention_end, D.detention_type_code, D.detention_summary,
SELECT t.teacher_id, s.bio_data, s.student_details, t.teacher_details, s.class_details FROM Teachers t JOIN Students s ON t.teacher_id = s.student_id JOIN Classes c ON s.student_id = c.student_id WHERE s.student_details LIKE '%data%' AND c.class_details LIKE '%net%' AND s.class_details NOT LIKE '%net%'
SELECT Teachers.teacher_id, Teachers.teacher_details FROM Teachers INNER JOIN Classes ON Classes.teacher_id = Teachers.teacher_id WHERE Classes.class_details LIKE '%data%' AND Classes.class_details NOT LIKE '%net%'
SELECT S.student_id, S.bio_data, S.student_details, S.address_details, S.achievement_type_code, S.achievement_details, S.achievement_id, S.date_achievement, S.date_of_loan, S.amount_of_loan, S.class_details, S.behaviour_monitoring_details, S.transcript_details, S.detention_summary, S.other_details FROM Students S JOIN Detention D ON S.student_id = D.student_id WHERE D.detention_summary IS NULL;
SELECT s.student_id, s.bio_data, s.student_details, s.address_details, s.achievement_details, s.detention_summary, s.other_details FROM Students s JOIN Detention d ON s.student_id = d.student_id WHERE d.detention_summary IS NULL;
SELECT student_id, date_of_loan, amount_of_loan FROM Student_Loans INNER JOIN Students ON Student_Loans.student_id = Students.student_id WHERE Student_Loans.date_of_loan IS NOT NULL AND Student_Loans.amount_of_loan >= 2;
SELECT S.student_id, S.amount_of_loan, S.date_of_loan, S.achievement_details, S.other_details FROM Students S JOIN Transcripts T ON S.student_id = T.student_id JOIN Behaviour_Monitoring B ON S.student_id = B.student_id JOIN Student_Events E ON S.student_id = E.student_id JOIN Achievements A ON E.event_type_code = A.achievement_type_code JOIN Ref_Achievement_Type A1 ON A.achievement_type_code = A1.achievement_type_code JOIN Ref_Detention_Type D ON A.detention_type_code = D.detention_type_code JOIN Detention D1 ON A.student_id = D1.student_id;
SELECT t.id, s.id AS detail FROM Students s JOIN Transcripts t ON s.student_id = t.student_id JOIN Classes c ON c.student_id = s.student_id JOIN Teachers t2 ON c.teacher_id = t2.teacher_id GROUP BY t.id, s.id ORDER BY t.id DESC;
SELECT S.id, T.id AS detail FROM Students S JOIN Transcripts T ON S.student_id = T.student_id JOIN Classes C ON S.student_id = C.student_id JOIN Behaviour_Monitoring B ON S.student_id = B.student_id JOIN Student_Events E ON S.student_id = E.student_id JOIN Detention D ON S.student_id = D.student_id JOIN Ref_Address_Types A ON S.student_id = A.address_id JOIN Addresses A1 ON A.address_id = A1.address_id JOIN Ref_Detention_Type D1 ON D.detention_type_code = D1.detention_type_code;
SELECT DISTINCT detention_summary FROM Detention;
