SELECT Students.student_id, Students.bio_data, Students.student_details, Addresses.address_details, Detention.datetime_detention_start, Detention.detention_summary FROM Students JOIN Addresses ON Addresses.address_id = Students.address_id JOIN Detention ON Detention.student_id = Students.student_id;
SELECT Students.bio_data, Transcripts.date_of_transcript FROM Students JOIN Transcripts ON Students.student_id = Transcripts.student_id;
SELECT student_id, date_of_transcript, transcript_details FROM Transcripts INNER JOIN Students ON Transcripts.student_id = Students.student_id;
SELECT b.behaviour_monitoring_details, COUNT(*) AS most_common_result_count FROM Behaviour_Monitoring b JOIN Students s ON b.student_id = s.student_id GROUP BY b.behaviour_monitoring_details ORDER BY COUNT(*) DESC LIMIT 1;
SELECT student_id, behaviour_monitoring_details, COUNT(*) AS count FROM Behaviour_Monitoring GROUP BY student_id ORDER BY count DESC;
SELECT Students.bio_data, Students.student_id, Students.student_details, Students_Addresses.address_id, Detention.datetime_detention_start, Detention.datetime_detention_end, Detention.detention_summary FROM Students JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id JOIN Detention ON Students_Addresses.address_id = Detention.address_id WHERE Students_Addresses.student_id NOT IN (SELECT student_id FROM Transcripts) AND Detention.student_id IN (SELECT student_id FROM Transcripts) AND Detention.datetime_detention_start > Detention.datetime_detention_end AND Detention.datetime_detention_end IS NOT NULL ORDER BY Students.student_id DESC;
{ "sql": "SELECT S.student_id, S.bio_data, S.student_details, B.behaviour_monitoring_details, T.transcript_details\nFROM Students S\nJOIN Behaviour_Monitoring B ON S.student_id = B.student_id\nJOIN Transcripts T ON S.student_id = T.student_id\nWHERE S.student_id IN (SELECT student_id FROM Transcripts T WHERE T.transcript_details LIKE '%common%')\nAND B.behaviour_monitoring_details IS NOT NULL\nAND T.transcript_details LIKE '%3%'"; }
SELECT Students.student_id, Students.bio_data, Students.student_details, Students.Addresses.address_id, Students.Addresses.address_type_code, Students.Addresses.address_details, Students.Addresses.date_from, Students.Addresses.date_to, Students.Addresses.address_type_code, Students.Addresses.address_details, Students.Addresses.date_from, Students.Addresses.date_to FROM Students JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id JOIN Addresses ON Students_Addresses.address_id = Addresses.address_id WHERE Students_Addresses.address_type_code = (SELECT address_type_code FROM Ref_Address_Types) ORDER BY Students.Addresses.date_from;
SELECT student_id, behaviour_monitoring_details, detention_summary FROM Behaviour_Monitoring JOIN Detention ON Behaviour_Monitoring.student_id = Detention.student_id GROUP BY behaviour_monitoring_details ORDER BY detention_summary DESC;
