SELECT COUNT(*) AS num_students, event_type_description AS event_type, transcript_details AS description FROM Student_Events JOIN Ref_Event_Types ON Student_Events.event_type_code = Ref_Event_Types.event_type_code GROUP BY event_type_description ORDER BY COUNT(*) DESC;
SELECT COUNT(*) AS total_students, Ref_Event_Types.event_type_code AS event_type_code, Ref_Event_Types.event_type_description AS event_type_description FROM Student_Events JOIN Ref_Event_Types ON Student_Events.event_type_code = Ref_Event_Types.event_type_code GROUP BY Ref_Event_Types.event_type_code ORDER BY COUNT(*) DESC;
SELECT A.achievement_type_code, A.achievement_details, A.achievement_type_description, B.student_id, B.bio_data, B.student_details, C.event_date, C.other_details, D.address_details, D.address_type_description, E.detention_summary, E.detention_type_code, E.datetime_detention_start, E.datetime_detention_end, E.detention_summary, E.other_details, F.class_details, F.teacher_id, F.class_id, F.class_details, F.teacher_details FROM Achievements A JOIN Students B ON A.student_id = B.student_id JOIN Student_Events C ON A.student_id = C.student_id JOIN Ref_Event_Types D ON C.event_type_code = D.event_type_code JOIN Ref_Address_Types E ON C.address_id = E.address_id JOIN Detention F ON A.student_id = F.student_id JOIN Ref_Address_Types E ON F.address_id = E.address_id JOIN Ref_Detention_Type F ON F.detention_type_code = E.detention_type_code;
SELECT Achievements.achievement_type_code, Achievements.achievement_details, Achievements.date_achievement FROM Achievements JOIN Students ON Achievements.student_id = Students.student_id JOIN Ref_Achievement_Type ON Achievements.achievement_type_code = Ref_Achievement_Type.achievement_type_code;
SELECT COUNT(DISTINCT student_id) FROM Students AS s JOIN Transcripts AS t ON s.student_id = t.student_id AND s.student_id NOT IN (SELECT student_id FROM Transcripts JOIN Behaviour_Monitoring ON Transcripts.student_id = Behaviour_Monitoring.student_id WHERE Behaviour_Monitoring.achievement_type_code IS NULL)
SELECT COUNT(DISTINCT student_id) FROM Students_Addresses WHERE date_from IS NULL OR date_to IS NULL;
SELECT Transcripts.date_of_transcript, Transcript_details.transcript_details FROM Transcripts JOIN Transcript_details ON Transcripts.transcript_id = Transcript_details.transcript_id WHERE Transcripts.student_id = (SELECT student_id FROM Students WHERE bio_data = 'Sample Bio Data')
SELECT Transcripts.date_of_transcript, Transcripts.transcript_details AS detail FROM Transcripts JOIN Students ON Transcripts.student_id = Students.student_id;
SELECT Transcripts.transcript_id, Transcripts.date_of_transcript, Transcripts.transcript_details, Achievements.achievement_details FROM Transcripts JOIN Achievements ON Transcripts.student_id = Achievements.student_id WHERE Achievements.achievement_type_code = 'A' AND Achievements.date_achievement IS NOT NULL;
{ "sql": "SELECT Transcripts.transcript_id, Transcripts.date_of_transcript, Transcripts.transcript_details, Transcripts.student_id, Transcripts.behaviour_monitoring_details, Transcripts.date_of_transcript\nFROM Transcripts\nJOIN Students ON Transcripts.student_id = Students.student_id\nJOIN Behaviour_Monitoring ON Transcripts.student_id = Behaviour_Monitoring.student_id\nJOIN Ref_Address_Types ON Students_Addresses.address_type_code = Ref_Address_Types.address_type_code\nJOIN Addresses ON Students_Addresses.address_id = Addresses.address_id\nJOIN Student_Loans ON Students_Addresses.student_id = Student_Loans.student_id\nJOIN Detention ON Student_Loans.student_id = Detention.student_id\nJOIN Ref_Detention_Type ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code\nJOIN Ref_Address_Types ON Students_Addresses.address_type_code = Ref_Address_Types.address_type_code\nJOIN Addresses ON Students_Addresses.address_id = Addresses.address_id\nJOIN Student_Loans ON Students_Addresses.student_id = Student_Loans.student_id\nJOIN Detention ON Student_Loans.student_id = Detention.student_id\nJOIN Ref_Detention_Type ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code\nJOIN Ref_Address_Types ON Students_Addresses.address_type_code = Ref_Address_Types.address_type_code\nJOIN Addresses ON Students_Addresses.address_id = Addresses.address_id\nJOIN Student_Loans ON Students_Addresses.student_id = Student_Loans.student_id\nJOIN Detention ON Student_Loans.student_id = Detention.student_id\nJOIN Ref_Detention_Type ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code\nJOIN Ref_Address_Types ON Students_Addresses.address_type_code = Ref_Address_Types.address_type_code\nJOIN Addresses ON Students_Addresses.address_id = Addresses.address_id\nJOIN Student_Loans ON Students_Addresses.student_id = Student_Loans.student_id\nJOIN Detention ON Student_Loans.student_id = Detention.student_id\nJOIN Ref_Detention_Type ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code\nJOIN Ref_Address_Types ON Students_Addresses.address_type_code = Ref_Address_Types.address_type_code\nJOIN Addresses ON Students_Addresses.address_id = Addresses.address_id\nJOIN Student_Loans ON Students_Addresses.student_id = Student_Loans.student_id\nJOIN Detention ON Student_Loans.student_id = Detention.student_id\nJOIN Ref_Detention_Type ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code\nJOIN Ref_Address_Types ON Students_Addresses.address_type_code = Ref_Address_Types.address_type_code\nJOIN Addresses ON Students_Addresses.address_id = Addresses.address_id\nJOIN Student_Loans ON Students_Addresses.student_id = Student_Loans.student_id\nJOIN Detention ON Student_Loans.student_id = Detention.student_id\nJOIN Ref_Detention_Type ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code\nJOIN Ref_Address_Types ON Students_Addresses.address_type_code = Ref_Address_Types.address_type_code\nJOIN Addresses ON Students_Addresses.address_id = Addresses.address_id\nJOIN Student_Loans ON Students_Addresses.student_id = Student_Loans.student_id\nJOIN Detention ON Student_Loans.student_id = Detention.student_id\nJOIN Ref_Detention_Type ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code\nJOIN Ref_Address_Types ON Students_Addresses.address_type_code = Ref_Address_Types.address_type_code\nJOIN Addresses ON Students_Addresses.address_id = Addresses.address_id\nJOIN Student_Loans ON Students_Addresses.student_id = Student_Loans.student_id\nJOIN Detention ON Student_Loans.student_id = Detention.student_id\nJOIN Ref_Detention_Type ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code\nJOIN Ref_Address_Types ON Students_Addresses.address_type_code = Ref_Address_Types.address_type_code\nJOIN Addresses ON Students_Addresses.address_id = Addresses.address
SELECT detention.datetime_detention_start, detention.datetime_detention_end, detention.detention_summary FROM Detention detention JOIN Students student ON detention.student_id = student.student_id
SELECT Detention.datetime_detention_start, Detention.datetime_detention_end, Detention.detention_summary, Detention.student_id FROM Detention JOIN Students ON Detention.student_id = Students.student_id WHERE Detention.detention_type_code = 'Student Detention' ORDER BY Detention.datetime_detention_start;
SELECT Students.student_id, Students.bio_data, Students.student_details, Students_Addresses.address_id, Addresses.address_details, Detention.datetime_detention_start, Detention.datetime_detention_end, Detention.detention_summary FROM Students JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id JOIN Addresses ON Students_Addresses.address_id = Addresses.address_id JOIN Detention ON Students_Addresses.student_id = Detention.student_id WHERE Students.bio_data LIKE '%Suite%' OR Students.student_details LIKE '%Suite%' OR Students_Addresses.address_id LIKE '%Suite%' OR Detention.datetime_detention_start LIKE '%Suite%' OR Detention.datetime_detention_end LIKE '%Suite%' ORDER BY student_id;
