SELECT S.student_id, R.address_type_code, R.address_type_description FROM Students AS S JOIN Ref_Address_Types AS R ON S.student_id = R.address_type_code JOIN Addresses ON S.address_id = R.address_id WHERE S.student_id IN (SELECT student_id FROM Students_Addresses WHERE date_from IS NULL OR date_to IS NULL)
SELECT Ref_Address_Types.address_type_code, Ref_Address_Types.address_type_description, Ref_Address_Types.address_type_code AS address_type_code, Ref_Address_Types.address_type_description AS address_type_description FROM Ref_Address_Types JOIN Students_Addresses ON Students_Addresses.student_id = Students.student_id JOIN Addresses ON Addresses.address_id = Students_Addresses.address_id WHERE Students_Addresses.date_from IS NULL OR Students_Addresses.date_to IS NULL;
SELECT Students.student_id, Students.bio_data, Students.student_details, Students_Addresses.address_id, Addresses.address_details FROM Students INNER JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id INNER JOIN Addresses ON Students_Addresses.address_id = Addresses.address_id WHERE Students.student_id NOT IN (SELECT student_id FROM Student_Loans WHERE Student_Loans.amount_of_loan IS NULL)
SELECT Students.student_id, Students.bio_data, Students.student_details FROM Students WHERE NOT EXISTS (SELECT 1 FROM Transcripts JOIN Students ON Transcripts.student_id = Students.student_id AND Transcripts.date_of_transcript IS NULL) AND NOT EXISTS (SELECT 1 FROM Behaviour_Monitoring JOIN Students ON Behaviour_Monitoring.student_id = Students.student_id AND Behaviour_Monitoring.behaviour_monitoring_details IS NULL) AND NOT EXISTS (SELECT 1 FROM Student_Loans JOIN Students ON Student_Loans.student_id = Students.student_id AND Student_Loans.date_of_loan IS NULL) AND NOT EXISTS (SELECT 1 FROM Classes JOIN Students ON Classes.student_id = Students.student_id AND Classes.class_details IS NULL) AND NOT EXISTS (SELECT 1 FROM Student_Addresses JOIN Addresses ON Student_Addresses.address_id = Addresses.address_id AND Student_Addresses.date_from IS NULL) AND NOT EXISTS (SELECT 1 FROM Detention JOIN Addresses ON Detention.student_id = Addresses.student_id AND Detention.datetime_detention_start IS NULL) AND NOT EXISTS (SELECT 1 FROM Achievements JOIN Students ON Achievements.student_id = Students.student_id AND Achievements.date_achievement IS NULL) AND NOT EXISTS (SELECT 1 FROM Ref_Event_Types JOIN Student_Events ON Student_Events.event_type_code = Ref_Event_Types.event_type_code AND Student_Events.event_date IS NULL) AND NOT EXISTS (SELECT 1 FROM Ref_Address_Types JOIN Student_Addresses ON Student_Addresses.address_type_code = Ref_Address_Types.address_type_code AND Student_Addresses.date_from IS NULL) AND NOT EXISTS (SELECT 1 FROM Ref_Detention_Type JOIN Detention ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code AND Detention.datetime_detention_start IS NULL) AND NOT EXISTS (SELECT 1 FROM Ref_Achievement_Type JOIN Achievements ON Achievements.achievement_type_code = Ref_Achievement_Type.achievement_type_code AND Achievements.date_achievement IS NULL) AND NOT EXISTS (SELECT 1 FROM Ref_Address_Types JOIN Addresses ON Addresses.address_type_code = Ref_Address_Types.address_type_code AND Addresses.address_id = Student_Addresses.address_id) AND NOT EXISTS (SELECT 1 FROM Ref_Detention_Type JOIN Detention ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code AND Detention.datetime_detention_start IS NULL) AND NOT EXISTS (SELECT 1 FROM Ref_Achievement_Type JOIN Achievements ON Achievements.achievement_type_code = Ref_Achievement_Type.achievement_type_code AND Achievements.date_achievement IS NULL)
SELECT S.student_id, S.bio_data, S.student_details, S.student_events.event_date, S.Detention.datetime_detention_start, S.Detention.datetime_detention_end FROM Students S JOIN Student_Events SE ON S.student_id = SE.student_id JOIN Detention D ON SE.event_type_code = D.event_type_code JOIN Students_Addresses SA ON S.student_id = SA.student_id WHERE SA.date_from = SA.date_to AND SA.date_from IS NOT NULL AND SA.date_to IS NOT NULL
SELECT s.student_id, s.bio_data, s.student_details, s.student_events.* FROM Students s JOIN Student_Events s_event ON s.student_id = s_event.student_id JOIN Detention d ON s_event.event_date = d.datetime_detention_end JOIN Ref_Address_Types r ON s_event.address_type_code = r.address_type_code JOIN Addresses a ON s_event.address_id = a.address_id JOIN Ref_Address_Types r2 ON a.address_type_code = r2.address_type_code;
SELECT MAX(detention.datetime_detention_start) AS start_date FROM Detention;
SELECT detention.datetime_detention_start AS detention_start_date FROM Detention INNER JOIN Students ON Detention.student_id = Students.student_id;
