SELECT Author.Name, Books_Order.amount FROM Author INNER JOIN Author_Book ON Author.idAuthor = Author_Book.ISBN INNER JOIN Book ON Author_Book.ISBN = Book.ISBN INNER JOIN Orders ON Orders.IdOrder = Books_Order.IdOrder INNER JOIN Books_Order ON Books_Order.IdOrder = Orders.IdOrder;
SELECT Author.Name, COUNT(Book.ISBN) AS TotalBooks_written FROM Author JOIN Author_Book ON Author.idAuthor = Author_Book.ISBN JOIN Book ON Author_Book.ISBN = Book.ISBN JOIN Orders ON Orders.IdOrder = Books_Order.IdOrder JOIN Client ON Orders.IdClient = Client.IdClient GROUP BY Author.Name
SELECT Book.ISBN, Orders.IdOrder, Orders.DateOrder, Orders.DateExped FROM Book INNER JOIN Author_Book ON Book.ISBN = Author_Book.ISBN INNER JOIN Author ON Author.idAuthor = Author_Book.idAuthor INNER JOIN Orders ON Orders.IdOrder = Author_Book.IdOrder;
SELECT B.ISBN, COUNT(B.ISBN) AS total_orders, A.Author, COUNT(A.Author) AS author_orders FROM Book B JOIN Author_Book A ON B.ISBN = A.ISBN JOIN Author A ON A.ISBN = A.ISBN JOIN Orders O ON O.IdClient = A.IdClient JOIN Books_Order B_O ON B_O.ISBN = B.ISBN GROUP BY B.ISBN, A.Author ORDER BY B.ISBN;
SELECT B.ISBN, B.Title, B.PurchasePrice, B.SalePrice, A.Name, A.Address, A.NumCC, O.DateOrder, O.DateExped FROM Books_Order O JOIN Author_Book A ON O.ISBN = A.ISBN JOIN Book B ON A.ISBN = B.ISBN JOIN Author A ON A.IdAuthor = A.IdAuthor;
SELECT B.ISBN, A.Name, O.DateOrder, B.PurchasePrice, B.SalePrice FROM Books_Order O JOIN Author_Book A ON O.ISBN = A.ISBN JOIN Book B ON A.ISBN = B.ISBN GROUP BY B.ISBN, A.Name, O.DateOrder, B.PurchasePrice, B.SalePrice;
SELECT Book.Title FROM Book INNER JOIN Author_Book ON Book.ISBN = Author_Book.ISBN INNER JOIN Author ON Author.idAuthor = Author_Book.Author_idAuthor INNER JOIN Orders ON Orders.IdClient = Client.IdClient INNER JOIN Books_Order ON Books_Order.ISBN = Book.ISBN INNER JOIN Orders ON Books_Order.IdOrder = Orders.IdOrder GROUP BY Book.ISBN ORDER BY COUNT(Orders.IdOrder) DESC LIMIT 1
SELECT Book.Title, COUNT(Orders.IdOrder) AS order_count FROM Books_Order INNER JOIN Orders ON Books_Order.IdOrder = Orders.IdOrder GROUP BY Book.ISBN ORDER BY order_count DESC LIMIT 1
SELECT Book.Title, Book.PurchasePrice FROM Book JOIN Author_Book ON Book.ISBN = Author_Book.ISBN JOIN Author ON Author.idAuthor = Author_Book.idAuthor GROUP BY Book.ISBN ORDER BY Book.PurchasePrice DESC;
SELECT B.Title, B.PurchasePrice FROM Books_Order B JOIN Books_Order AS B2 ON B.ISBN = B2.ISBN JOIN Orders ON B.IdOrder = B2.IdOrder JOIN Client ON B.IdClient = B2.IdClient JOIN Author_Book ON B.ISBN = Author_Book.ISBN JOIN Author ON Author_Book.Author = Author.idAuthor ORDER BY B.PurchasePrice DESC LIMIT 1;
SELECT Book.Title FROM Book INNER JOIN Author_Book ON Book.ISBN = Author_Book.ISBN INNER JOIN Author ON Author.ISBN = Author_Book.Author INNER JOIN Orders ON Orders.IdClient = Author.Client INNER JOIN Books_Order ON Books_Order.ISBN = Book.ISBN;
SELECT Book.Title, Author_Book.Author FROM Book JOIN Author_Book ON Book.ISBN = Author_Book.ISBN;
SELECT Name FROM Client JOIN Orders ON Client.IdClient = Orders.IdClient WHERE Orders.DateOrder IS NOT NULL;
SELECT DISTINCT Name FROM Client JOIN Orders ON Client.IdClient = Orders.IdClient;
SELECT Name, COUNT(*) AS num_orders FROM Client JOIN Orders ON Client.IdClient = Orders.IdClient GROUP BY Name
SELECT Name, COUNT(*) AS OrderCounts FROM Client JOIN Orders ON Client.IdClient = Orders.IdClient GROUP BY Name;
SELECT Name FROM Client JOIN Orders ON Client.IdClient = Orders.IdClient ORDER BY Orders.DateOrder DESC LIMIT 1
SELECT Name FROM Client JOIN Orders ON Client.IdClient = Orders.IdClient JOIN Books_Order ON Books_Order.ISBN = Book.ISBN JOIN Author_Book ON Author_Book.ISBN = Book.ISBN JOIN Author ON Author.idAuthor = Author_Book.idAuthor WHERE Orders.IdOrder = (SELECT IdOrder FROM Orders WHERE DateOrder IS NULL OR DateExped IS NULL) GROUP BY Name ORDER BY COUNT(*) DESC LIMIT 1
SELECT Client.Name, SUM(Books_Order.amount) AS total_amount FROM Client JOIN Orders ON Client.IdClient = Orders.IdClient JOIN Books_Order ON Books_Order.ISBN = Book.ISBN JOIN Author_Book ON Author_Book.ISBN = Book.ISBN JOIN Author ON Author.idAuthor = Author_Book.idAuthor GROUP BY Client.IdClient;
SELECT Client.Name, SUM(Books_Order.amount) AS total_amount_per_client FROM Client INNER JOIN Books_Order ON Client.IdClient = Books_Order.IdClient GROUP BY Client.IdClient
SELECT Name, COUNT(*) AS total_books_ordered FROM Orders JOIN Books_Order ON Orders.IdOrder = Books_Order.IdOrder JOIN Book ON Books_Order.ISBN = Book.ISBN JOIN Author_Book ON Book.ISBN = Author_Book.ISBN JOIN Author ON Author.ISBN = Author_Book.Author GROUP BY Name ORDER BY COUNT(*) DESC LIMIT 1;
SELECT Name FROM Client JOIN Orders ON Client.IdClient = Orders.IdClient JOIN Books_Order ON Books_Order.IdOrder = Orders.IdOrder JOIN Book ON Books_Order.ISBN = Book.ISBN GROUP BY Name ORDER BY (SELECT MAX(amount) FROM Books_Order) DESC LIMIT 1;
