SELECT u.user_id, s.search_seq FROM Users u JOIN User_Searches s ON u.user_id = s.user_id JOIN Property_Features p ON s.property_id = p.property_id JOIN Features f ON p.feature_id = f.feature_id JOIN Properties p2 ON p.property_id = p2.property_id JOIN Ref_Property_Types pt ON p.property_type_code = pt.property_type_code JOIN Ref_Room_Types rt ON p.room_type_code = rt.room_type_code JOIN Rooms r ON p.room_id = r.room_id GROUP BY u.user_id, s.search_seq ORDER BY s.search_seq;
SELECT MAX(search_datetime) AS latest_search_time FROM User_Searches;
SELECT MAX(search_datetime) AS most_recent_search_time FROM User_Searches;
SELECT user_search_seq, search_datetime, search_string FROM User_Searches ORDER BY search_string DESC;
SELECT search_string, datestamp FROM User_Searches JOIN Users ON User_Searches.user_id = Users.user_id ORDER BY search_string DESC;
SELECT Addresses.zip_postcode FROM Addresses INNER JOIN Users ON Addresses.user_address_id = Users.user_address_id WHERE Users.is_buyer IS NULL OR Users.is_seller IS NULL OR Users.is_buyer + Users.is_seller <= 2;
SELECT Addresses.zip_postcode FROM Addresses INNER JOIN Users ON Addresses.address_id = Users.user_address_id WHERE Users.is_buyer IS NULL OR Users.is_seller IS NULL OR Users.is_buyer + Users.is_seller = 0;
SELECT Users.user_id, Users.user_category_code, Users.age_category_code, Users.first_name, Users.middle_name, Users.last_name, Users.login_name, Users.password, Users.date_registered, Users.is_buyer, Users.is_seller, Users.other_user_details FROM Users JOIN User_Searches ON Users.user_id = User_Searches.user_id JOIN Features ON User_Searches.search_string = Features.feature_name JOIN Ref_Property_Types ON Features.feature_id = Ref_Property_Types.property_type_code JOIN Addresses ON Users.user_address_id = Addresses.address_id JOIN Ref_Room_Types ON Rooms.room_type_code = Ref_Room_Types.room_type_code JOIN Rooms ON Rooms.property_id = Properties.property_id JOIN Properties ON Properties.property_id = Rooms.room_id JOIN User_Property_History ON User_Property_History.property_id = Properties.property_id JOIN Property_Features ON Property_Features.feature_id = Property_Features.feature_value JOIN Property_Photos ON Property_Photos.property_id = Properties.property_id WHERE User_Searches.search_string = 'Only One Search' ORDER BY Users.user_id;
SELECT user_id, user_category_code, user_address_id FROM Users JOIN User_Searches ON Users.user_id = User_Searches.user_id JOIN Properties ON User_Searches.property_id = Properties.property_id JOIN Property_Features ON Properties.property_id = Property_Features.property_id JOIN Ref_Property_Types ON Properties.property_type_code = Ref_Property_Types.property_type_code JOIN Ref_Room_Types ON Properties.room_type_code = Ref_Room_Types.room_type_code JOIN Ref_User_Categories ON Users.user_category_code = Ref_User_Categories.user_category_code WHERE User_Searches.search_string = '' AND User_Searches.search_datetime = '' AND User_Searches.search_seq = '' GROUP BY user_id, user_category_code, user_address_id ORDER BY user_id;
SELECT DISTINCT age_category_description, age_category_code FROM Ref_Age_Categories;
SELECT Users.age_category_code AS age_category, Users.first_name AS first_name, Users.last_name AS last_name FROM Users JOIN Ref_Age_Categories ON Users.age_category_code = Ref_Age_Categories.age_category_code WHERE Users.date_registered IS NULL;
SELECT Users.login_name, Users.first_name FROM Users JOIN Ref_User_Categories ON Users.user_category_code = Ref_User_Categories.user_category_code WHERE Users.age_category_code = (SELECT age_category_code FROM Ref_Age_Categories WHERE age_category_description = 'Senior' AND Ref_Property_Types.property_type_code = (SELECT property_type_code FROM Ref_Property_Types WHERE property_type_description = 'House' AND Users.user_address_id = (SELECT address_id FROM Addresses WHERE Addresses.town_city = 'City' AND Addresses.zip_postcode = 'ZIP') LIMIT 1) AND Users.is_seller = 1;
SELECT Users.first_name, Users.login_name FROM Users INNER JOIN Addresses ON Users.user_address_id = Addresses.address_id INNER JOIN Ref_Property_Types ON Addresses.property_type_code = Ref_Property_Types.property_type_code INNER JOIN Users ON Users.user_address_id = Users.user_address_id INNER JOIN Ref_Property_Types ON Users.user_property_type_code = Ref_Property_Types.property_type_code INNER JOIN Users ON Users.user_address_id = Users.user_address_id INNER JOIN Ref_Property_Types ON Users.user_property_type_code = Ref_Property_Types.property_type_code INNER JOIN Users ON Users.user_address_id = Users.user_address_id INNER JOIN Ref_Property_Types ON Users.user_property_type_code = Ref_Property_Types.property_type_code;
SELECT COUNT(*) AS total_searches FROM User_Searches;
SELECT COUNT(*) AS count_of_searches FROM User_Searches;
SELECT date_registered FROM Users WHERE login_name = 'ratione'
