SELECT DISTINCT user_search_string FROM User_Searches WHERE user_id NOT IN (SELECT user_id FROM Users WHERE owner_user_id IS NULL)
SELECT Users.last_name, Users.user_id FROM Users JOIN Properties ON Users.user_id = Properties.owner_user_id JOIN Ref_Property_Types ON Properties.property_type_code = Ref_Property_Types.property_type_code JOIN Ref_Room_Types ON Properties.room_count = Ref_Room_Types.room_count JOIN Users ON Users.user_id = Users.user_address_id JOIN Ref_Property_Types ON Users.user_address_id = Ref_Property_Types.property_type_code JOIN Ref_Room_Types ON Users.user_address_id = Ref_Room_Types.room_type_code WHERE Users.is_buyer = 1 AND Users.is_seller = 1 AND Users.date_registered > DATE_SUB(CURRENT_DATE, INTERVAL 2 DAY) AND Users.last_name IS NOT NULL;
SELECT Users.last_name, Users.user_id FROM Users INNER JOIN User_Property_History ON Users.user_id = User_Property_History.user_id INNER JOIN Properties ON User_Property_History.property_id = Properties.property_id INNER JOIN Property_Features ON Properties.property_id = Property_Features.property_id INNER JOIN Features ON Property_Features.feature_id = Features.feature_id INNER JOIN Ref_Property_Types ON Properties.property_type_code = Ref_Property_Types.property_type_code INNER JOIN Ref_Room_Types ON Rooms.room_type_code = Ref_Room_Types.room_type_code INNER JOIN Rooms ON Rooms.property_id = Rooms.property_id WHERE Users.is_buyer OR Users.is_seller AND Users.date_registered >= DATE_SUB(CURRENT_DATE, INTERVAL 1 DAY) GROUP BY Users.last_name, Users.user_id ORDER BY Users.last_name;
