SELECT meetings.meeting_id, COUNT(staff.staff_id) AS num_staff_per_meeting FROM Meetings JOIN Staff_in_Meetings ON Meetings.meeting_id = Staff_in_Meetings.meeting_id JOIN Staff ON Staff_in_Meetings.staff_id = Staff.staff_id GROUP BY meetings.meeting_id
