SELECT staff_id FROM Staff_in_Meetings INNER JOIN Staff ON Staff_in_Meetings.staff_id = Staff.staff_id WHERE Staff_in_Meetings.meeting_type = 'Meeting' AND Staff_in_Meetings.billable_yn = 'Y' AND (SELECT COUNT(*) FROM Meetings WHERE client_id = Staff.client_id) = 1;
SELECT COUNT(*) FROM Staff INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id;
SELECT COUNT(DISTINCT staff.staff_id) FROM Staff JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id;
