SELECT C.client_id, C.client_details, M.client_id, M.meeting_outcome, M.meeting_type, M.billable_yn, M.start_date_time, M.end_date_time, M.purpose_of_meeting, M.other_details FROM Clients C JOIN Meetings M ON C.client_id = M.client_id JOIN Staff S ON S.staff_id = M.staff_id JOIN Invoices I ON M.client_id = I.client_id JOIN Payments P ON I.invoice_id = P.invoice_id WHERE M.billable_yn = 'Y' OR M.invoice_status = 'A';
SELECT Clients.client_id, Clients.client_details, Clients.sic_code, Clients.agency_id, Clients.client_id, Clients.client_details, Clients.sic_code, Clients.client_details FROM Clients JOIN Invoices ON Clients.client_id = Invoices.client_id JOIN Meetings ON Invoices.client_id = Meetings.client_id JOIN Staff ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Staff_in_Meetings ON Staff_in_Meetings.staff_id = Staff.staff_id WHERE Meetings.meeting_type = 'Meeting' OR Meetings.billable_yn = 'Y' OR Meetings.purpose_of_meeting = 'Meeting'
SELECT staff_id, staff_details FROM Staff INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id WHERE staff_details LIKE '%s%' AND staff_details IS NOT NULL;
SELECT staff_id, staff_details FROM Staff INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id WHERE staff_details LIKE '%s%' AND staff_in_Meetings.meeting_outcome = 'at least 1 meeting' AND staff_in_Meetings.meeting_type = 'meeting'
SELECT C.client_id, C.sic_code, C.agency_id FROM Clients C JOIN Meetings M ON C.client_id = M.client_id WHERE M.meeting_outcome = 'attended' AND M.meeting_type IS NOT NULL AND M.billable_yn = 'Y' ORDER BY C.client_id;
SELECT Clients.client_id, Clients.sic_code, Clients.agency_id, Clients.client_details, Invoices.invoice_id, Invoices.invoice_status, Invoices.invoice_details, Meetings.meeting_outcome, Meetings.meeting_type, Payments.payment_details FROM Clients JOIN Invoices ON Clients.client_id = Invoices.client_id JOIN Meetings ON Clients.client_id = Meetings.client_id JOIN Staff_in_Meetings ON Meetings.meeting_id = Staff_in_Meetings.meeting_id JOIN Staff ON Staff_in_Meetings.staff_id = Staff.staff_id WHERE Meetings.client_id = Clients.client_id AND Meetings.meeting_outcome = 'attended' AND Meetings.meeting_type = 'meeting' AND Meetings.billable_yn = 'y' AND Invoices.invoice_status = 'paid' AND Invoices.invoice_details IS NOT NULL;
SELECT M.start_date_time, M.end_date_time, S.staff_id, S.staff_details, C.client_id, C.client_details FROM Meetings M JOIN Staff S ON M.meeting_id = S.meeting_id JOIN Clients C ON M.client_id = C.client_id;
SELECT M.end_date_time, C.client, S.staff_id, S.staff_details FROM Meetings M INNER JOIN Clients C ON M.client_id = C.client_id INNER JOIN Staff S ON M.staff_id = S.staff_id;
